import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";

const css = readFileSync(new URL("./tokens.css", import.meta.url));

test("vendored tokens.css is byte-for-byte the recorded verdigris output", () => {
  // Generated by verdigris build/tokens.py (WCAG-checked). Never edit here;
  // re-vendor and update SOURCE.md and this hash together.
  assert.equal(
    createHash("sha256").update(css).digest("hex"),
    "b073453d7fca0cef31b5e7d8b70d1298d483f23a1d3d6bfb2984a474d1d52eb2",
  );
});

test("it defines the four themes spall's picker offers", () => {
  const text = css.toString("utf8");
  assert.match(text, /^\/\* verdigris design tokens v0\.3\.0\. GENERATED/);
  for (const theme of ["rust-light", "blued", "blued-light"]) {
    assert.ok(text.includes(`[data-theme="${theme}"]`), theme);
  }
  assert.ok(text.includes(':root, [data-theme="rust"]'), "rust is the default");
});

// Icons: suite marks copied byte-for-byte from verdigris icons/ at v0.3.0;
